// ─── Product Selector ───
function loadCopyProducts(){
  var el=document.getElementById('copyProducts');
  if(!el)return;
  fetch('product_library.json?v='+Date.now()).then(function(r){return r.json()}).then(function(d){
    allProductsData=d.items||[];
    renderCopyProductSelector();
  }).catch(function(){
    el.innerHTML='<span style="color:var(--text-dim)">产品库加载失败</span>';
  });
}

function renderCopyProductSelector(){
  var el=document.getElementById("copyProducts");
  if(!el)return;
  var sorted=allProductsData.slice().sort(function(a,b){return (b.sales||0)-(a.sales||0)});
  var top=sorted.slice(0,10);
  var html='<input id="copyProductSearch" oninput="filterCopyProducts()" placeholder="🔍 搜索产品...（销量Top10快捷选，搜索可查全部）" style="width:100%;padding:6px 8px;border:1px solid var(--border);border-radius:4px;font-size:11px;margin-bottom:8px">';
  html+='<div id="copyProductList" style="max-height:200px;overflow-y:auto;font-size:11px">';
  top.forEach(function(p,i){
    var checked=copyProducts.indexOf(p.name)>=0?' checked':'';
    var icon=i<3?["🥇","🥈","🥉"][i]:"#"+(i+1);
    var safeName=p.name.replace(/'/g,"&#39;").replace(/"/g,"&quot;");
    html+='<label style="display:flex;align-items:center;gap:4px;padding:2px 4px;cursor:pointer"><span style="font-size:10px;width:22px;text-align:center">'+icon+'</span><input type="checkbox"'+checked+' data-prod="'+safeName+'" onchange="toggleCopyProduct(this,this.dataset.prod)"><span>'+p.name+'</span><span style="color:var(--text-dim);margin-left:auto;font-size:10px">¥'+p.price+'</span></label>';
  });
  html+='</div><div style="font-size:10px;color:var(--text-muted);margin-top:4px">已选 <span id="copyProductCount">'+copyProducts.length+'</span> 款 · 搜索可查全部'+(sorted.length-top.length)+'款</div>';
  el.innerHTML=html;
}

function filterCopyProducts(){
  var q=(document.getElementById("copyProductSearch").value||"").toLowerCase();
  var el=document.getElementById("copyProductList");
  if(!el)return;
  if(!q){renderCopyProductSelector();return;}
  var matches=allProductsData.filter(function(p){return p.name.toLowerCase().indexOf(q)>=0}).slice(0,20);
  var html='';
  matches.forEach(function(p){
    var checked=copyProducts.indexOf(p.name)>=0?' checked':'';
    var safeName=p.name.replace(/'/g,"&#39;").replace(/"/g,"&quot;");
    html+='<label style="display:flex;align-items:center;gap:4px;padding:2px 4px;cursor:pointer"><input type="checkbox"'+checked+' data-prod="'+safeName+'" onchange="toggleCopyProduct(this,this.dataset.prod)"><span>'+p.name+'</span><span style="color:var(--text-dim);margin-left:auto;font-size:10px">¥'+p.price+' · '+p.category+'</span></label>';
  });
  var exactMatch=matches.some(function(p){return p.name.toLowerCase()===q;});
  if(q&&!exactMatch){html='<div onclick="useCustomProduct()" style="padding:5px 8px;background:var(--brand-light);color:var(--brand);border-radius:4px;cursor:pointer;font-weight:600;font-size:11px;margin-bottom:4px">📝 使用「'+q+'」作为产品名</div>'+html;}
  if(!matches.length&&!q)html='<div style="padding:8px;color:var(--text-dim)">无匹配产品</div>';
  el.innerHTML=html;
}


function toggleCopyProduct(cb,name){
  if(cb.checked){copyProducts=[name];renderCopyProductSelector();}
  else{copyProducts=[];}
  document.getElementById('copyProductCount').textContent=copyProducts.length;
}

// ─── 花字引擎 ───
function pickHuaZi(poolKey,storageKey,avoidCount){
  var pool=HUA_ZI_POOLS[poolKey]||[];
  if(!pool.length)return '';
  var used=[];
  try{used=JSON.parse(localStorage.getItem(storageKey)||'[]');}catch(e){}
  var candidates=[];
  for(var i=0;i<pool.length;i++){if(used.indexOf(i)<0)candidates.push(i);}
  if(!candidates.length){candidates=[];for(var j=0;j<pool.length;j++)candidates.push(j);}
  var pick=candidates[Math.floor(Math.random()*candidates.length)];
  used.push(pick);
  while(used.length>avoidCount)used.shift();
  localStorage.setItem(storageKey,JSON.stringify(used));
  return pool[pick];
}

function pickCTA(dayKey,storageKey){
  var pool=CTA_POOLS[dayKey]||CTA_POOLS['thu'];
  var used=[];
  try{used=JSON.parse(localStorage.getItem(storageKey)||'[]');}catch(e){}
  var candidates=[];
  for(var i=0;i<pool.length;i++){if(used.indexOf(i)<0)candidates.push(i);}
  if(!candidates.length){for(var j=0;j<pool.length;j++)candidates.push(j);}
  var pick=candidates[Math.floor(Math.random()*candidates.length)];
  used.push(pick);
  while(used.length>3)used.shift();
  localStorage.setItem(storageKey,JSON.stringify(used));
  return pool[pick];
}

// ─── 品类卖点 ───
function getSellingPoint(productName){
  if(!productName)return PRODUCT_SELLING['default'];
  for(var k in PRODUCT_SELLING){if(k==='default')continue;if(productName.indexOf(k)>=0)return PRODUCT_SELLING[k];}
  return PRODUCT_SELLING['default'];
}

// ─── 行处理（≤22字，emoji行尾）───
function wrapLine(text){
  if(!text)return '';
  if(text.length<=22)return text;
  var result=[];
  var current='';
  for(var i=0;i<text.length;i++){
    current+=text[i];
    if(current.length>=22||'，。！？、｜'.indexOf(text[i])>=0){
      if(current.trim())result.push(current.trim());
      current='';
    }
  }
  if(current.trim())result.push(current.trim());
  if(!result.length)result=[text];
  return result;
}

function eji(line){
  if(!line||!line.trim())return line;
  if(line.charAt(0)==='#'||line.indexOf('http')===0||line.indexOf('//')===0)return line;
  if(/[\u{1F300}-\u{1FAFF}]/u.test(line))return line;
  // Contextual emoji based on content
  if(/外卖|配送|到家|下单|直达/.test(line))return line+'🛵';
  if(/冰|冻|凉|冷|降温/.test(line))return line+'🧊';
  if(/热|高温|暑|晒|闷/.test(line))return line+'🔥';
  if(/甜|蜜|好吃|美味/.test(line))return line+'😋';
  if(/健康|维C|营养|养生/.test(line))return line+'💪';
  if(/懒|轻松|方便|省/.test(line))return line+'😎';
  if(/福利|惊喜|会员|特权|彩蛋/.test(line))return line+'🎁';
  if(/价格|¥|元|钱|省/.test(line))return line+'💰';
  if(/快|秒|速|限时|倒计时/.test(line))return line+'⚡';
  if(/周末|宅|追剧|聚会|沙发/.test(line))return line+'🎬';
  return line+'🍉';
}

function linesToCopy(lines){
  var out=[];
  lines.forEach(function(l){
    if(!l||!l.trim()){out.push('');return;}
    var parts=wrapLine(l);
    if(typeof parts==='string'){out.push(eji(parts));}
    else{parts.forEach(function(p){out.push(eji(p));});}
  });
  return out.join('\n').replace(/\n\n\n+/g,'\n\n');
}

// ─── 缩短产品名 ───
function shortName(name){
  return name.replace(/【[^】]*】/g,'').replace(/[（(].*[）)]/g,'').trim()||name;
}

